// Polling del GLB legato a QUESTA esecuzione (tramite prompt_id di ComfyUI)
const history   = $input.first().json;
const agentData = $("Estrai JSON dall'agente2").first().json;
const promptId  = $('Comfy3D - Pixal').first().json.prompt_id;

if (!promptId) throw new Error('prompt_id mancante nella risposta di Comfy3D - Pixal');

const attempts = $runIndex + 1;   // conta le esecuzioni di questo nodo nel loop
const MAX_ATTEMPTS = 60;          // con Wait da 10 s = 10 minuti

// /api/history/{prompt_id} restituisce {} finché il prompt non è completato
const entry = history[promptId];

if (entry?.status?.status_str === 'error') {
  throw new Error(`ComfyUI: esecuzione fallita per ${promptId} — ${JSON.stringify(entry.status.messages ?? []).substring(0, 400)}`);
}

// Cerca qualunque file .glb in qualunque chiave degli output
const glbs = [];
for (const out of Object.values(entry?.outputs ?? {})) {
  for (const val of Object.values(out ?? {})) {
    if (!Array.isArray(val)) continue;
    for (const f of val) {
      if (typeof f?.filename === 'string' && f.filename.toLowerCase().endsWith('.glb')) glbs.push(f);
    }
  }
}
const glb = glbs.at(-1) ?? null;

// GLB non ancora pronto
if (!glb) {
  if (entry?.status?.completed) {
    throw new Error(`Prompt ${promptId} completato ma nessun .glb trovato. Outputs: ${JSON.stringify(entry.outputs).substring(0, 600)}`);
  }
  if (attempts >= MAX_ATTEMPTS) {
    throw new Error(`Timeout: nessun GLB per ${promptId} dopo ${attempts} tentativi`);
  }
  return [{ json: { _ready: false, _attempts: attempts, prompt_id: promptId } }];
}

// GLB pronto
const host = '10.54.15.50';
const port = 8188;
const glbUrl = `http://${host}:${port}/view?filename=${encodeURIComponent(glb.filename)}`
  + `&type=${glb.type || 'output'}&subfolder=${encodeURIComponent(glb.subfolder || 'mesh')}`;

return [{ json: {
  _ready: true,
  _attempts: attempts,
  status: 'ready',
  glb_url: glbUrl,
  prompt_id: promptId,
  object_name: agentData.object_name,
  session_id: agentData.session_id,
  message: 'Oggetto generato con successo!'
}}];

